package net.officefloor.hq.app.settings;

import java.math.BigDecimal;
import java.math.RoundingMode;
import java.time.LocalDate;
import java.util.List;
import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.rollup.RollupService;
import net.officefloor.hq.app.sheet.Sheet;
import net.officefloor.hq.app.sheet.SheetRepository;
import net.officefloor.hq.app.sheet.SheetService;
import org.springframework.dao.DataIntegrityViolationException;
import org.springframework.http.HttpStatus;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import org.springframework.web.server.ResponseStatusException;

/**
 * A sheet's settings: the role each user name has; the clerk limit, the floor, the terms (the sheet's and each
 * grade's), the late percent and the cap, each recorded from a from-date; the policy date and the period numbering
 * from.
 */
@Service
public class SettingsService {

    private final SheetRoleRepository roles;
    private final SheetRepository sheetRepository;
    private final SheetService sheets;
    private final RollupService rollup;
    private final Audit audit;

    public SettingsService(SheetRoleRepository roles, SheetRepository sheetRepository,
            SheetService sheets, RollupService rollup, Audit audit) {
        this.roles = roles;
        this.sheetRepository = sheetRepository;
        this.sheets = sheets;
        this.rollup = rollup;
        this.audit = audit;
    }

    /** The roles set on the sheet, by user name. */
    @Transactional(readOnly = true)
    public List<SheetRole> roles(String sheetId) {
        return roles.findBySheetIdOrderByUserAsc(sheetId);
    }

    /** The user's role on the sheet: clerk unless set otherwise. */
    @Transactional(readOnly = true)
    public String roleOf(String sheetId, String user) {
        return roles.findBySheetIdAndUser(sheetId, user).map(SheetRole::getRole).orElse(SheetRole.CLERK);
    }

    /** Sets the user's role on the sheet; refused unless it is clerk or steward. */
    @Transactional
    public SheetRole setRole(String by, String sheetId, String user, String role) {
        if (!SheetRole.CLERK.equals(role) && !SheetRole.STEWARD.equals(role)) {
            throw new ResponseStatusException(HttpStatus.UNPROCESSABLE_CONTENT, "A role is clerk or steward.");
        }
        sheets.lock(sheetId);
        SheetRole r = roles.findBySheetIdAndUser(sheetId, user).orElseGet(() -> new SheetRole(sheetId, user, role));
        r.setRole(role);
        SheetRole saved;
        try {
            saved = roles.saveAndFlush(r);
        } catch (DataIntegrityViolationException e) {
            throw new ResponseStatusException(HttpStatus.CONFLICT, "That role was just set by someone else.");
        }
        audit.recordOnCommit("ROLE_SET sheet=" + sheetId + " by=" + by + " user=" + user + " role=" + role);
        return saved;
    }

    /** Records the sheet's clerk limit (null for no limit) from the date; null for the sheet's today. */
    @Transactional
    public Sheet setClerkLimit(String by, String sheetId, BigDecimal limit, LocalDate from) {
        return record(by, sheetId, Sheet.CLERK_LIMIT, limit == null ? null : money(limit), from, false);
    }

    /**
     * Records the sheet's terms from the date (null for the sheet's today): the days after its date a claim dated on
     * or after it is due by. Claims already added keep the due-by they were given.
     */
    @Transactional
    public Sheet setTerms(String by, String sheetId, int terms, LocalDate from) {
        return record(by, sheetId, Sheet.TERMS, String.valueOf(terms), from, false);
    }

    /**
     * Records the terms for one grade from the date (null for the sheet's today): the days after its date a claim is
     * due by when it is dated on or after it and its person has the grade on its date. Claims already added keep the
     * due-by they were given.
     */
    @Transactional
    public Sheet setGradeTerms(String by, String sheetId, String grade, int terms, LocalDate from) {
        return record(by, sheetId, Sheet.TERMS + "-" + grade, String.valueOf(terms), from, false);
    }

    /**
     * Records the sheet's late percent from the date (null for the sheet's today): the percent of an overdue claim's
     * figure added for every full 30 days it is overdue, for a claim dated on or after it. Settled figures keep what
     * they were; the live figures it moves are rolled up.
     */
    @Transactional
    public Sheet setLatePct(String by, String sheetId, BigDecimal latePct, LocalDate from) {
        return record(by, sheetId, Sheet.LATE_PCT, money(latePct), from, true);
    }

    /**
     * Sets the sheet's policy date (null for blank: the sheet's today): a claim rounded by a date before it rounds
     * half up, one on or after it half to even. Settled and stated figures keep what they were; the live figures it
     * moves are rolled up.
     */
    @Transactional
    public Sheet setPolicyDate(String by, String sheetId, LocalDate policyDate) {
        Sheet sheet = sheets.lock(sheetId);
        RollupService.Snapshot before = rollup.snapshot(sheetId);
        sheet.setPolicyDate(policyDate);
        Sheet saved = sheetRepository.saveAndFlush(sheet);
        audit.recordOnCommit("SETTING_CHANGED sheet=" + sheetId + " by=" + by + " key=policy-date value="
                + (policyDate == null ? "" : policyDate.toString()));
        rollup.recordChanges(by, sheetId, before);
        return saved;
    }

    /**
     * Sets the sheet's period numbering from (null for blank: off): while it is set and the sheet's today is on or
     * after it, a claim opened is numbered within its period. Claims already numbered keep their numbers.
     */
    @Transactional
    public Sheet setPeriodNumberingFrom(String by, String sheetId, LocalDate from) {
        Sheet sheet = sheets.lock(sheetId);
        sheet.setPeriodNumberingFrom(from);
        Sheet saved = sheetRepository.saveAndFlush(sheet);
        audit.recordOnCommit("SETTING_CHANGED sheet=" + sheetId + " by=" + by + " key=period-numbering-from value="
                + (from == null ? "" : from.toString()));
        return saved;
    }

    /**
     * Records the sheet's floor from the date (null for the sheet's today): the least the live due of a claim dated
     * on or after it can be. Settled, stated and closed-period figures keep what they were; the live figures it moves
     * are rolled up.
     */
    @Transactional
    public Sheet setFloor(String by, String sheetId, BigDecimal floor, LocalDate from) {
        return record(by, sheetId, Sheet.FLOOR, money(floor), from, true);
    }

    /**
     * Records the sheet's cap (null for none) from the date (null for the sheet's today): the most a person's
     * due-total can be while it is in force on the sheet's today. The due-totals it moves are rolled up.
     */
    @Transactional
    public Sheet setCap(String by, String sheetId, BigDecimal cap, LocalDate from) {
        return record(by, sheetId, Sheet.CAP, cap == null ? null : money(cap), from, true);
    }

    /**
     * Records the sheet's proof threshold (null for none) from the date (null for the sheet's today): a claim dated
     * on or after it whose due is above it cannot be settled or approved while it has no proof.
     */
    @Transactional
    public Sheet setProofThreshold(String by, String sheetId, BigDecimal threshold, LocalDate from) {
        return record(by, sheetId, Sheet.PROOF_THRESHOLD, threshold == null ? null : money(threshold), from, false);
    }

    /**
     * Records the dated setting's value (null for none) from the date, or from the sheet's today when none is given,
     * replacing a value already recorded from that date. The audit line carries the from-date only when one was
     * given. When it can move live figures, the ones it moves are rolled up.
     */
    private Sheet record(String by, String sheetId, String key, String value, LocalDate from, boolean rollsUp) {
        Sheet sheet = sheets.lock(sheetId);
        RollupService.Snapshot before = rollsUp ? rollup.snapshot(sheetId) : null;
        sheet.record(key, from == null ? sheet.getToday() : from, value);
        Sheet saved = sheetRepository.saveAndFlush(sheet);
        audit.recordOnCommit("SETTING_CHANGED sheet=" + sheetId + " by=" + by + " key=" + key + " value="
                + (value == null ? "" : value) + (from == null ? "" : " from=" + from));
        if (rollsUp) {
            rollup.recordChanges(by, sheetId, before);
        }
        return saved;
    }

    private static String money(BigDecimal value) {
        return value.setScale(2, RoundingMode.UNNECESSARY).toPlainString();
    }

    /**
     * Whether the user settling a claim with the due (null for n/a) needs a steward's approval: they are a clerk and
     * the due is above the sheet's clerk limit. A steward settles anything, and an n/a due is within any limit.
     */
    @Transactional(readOnly = true)
    public boolean aboveClerkLimit(String sheetId, String user, BigDecimal due) {
        BigDecimal limit = sheets.load(sheetId).getClerkLimit();
        if (limit == null || due == null || due.compareTo(limit) <= 0) {
            return false;
        }
        return !isSteward(sheetId, user);
    }

    /** Whether the user is a steward of the sheet. */
    @Transactional(readOnly = true)
    public boolean isSteward(String sheetId, String user) {
        return SheetRole.STEWARD.equals(roleOf(sheetId, user));
    }
}
package net.officefloor.hq.app.settings;

import jakarta.validation.Valid;
import jakarta.validation.constraints.DecimalMin;
import jakarta.validation.constraints.Max;
import jakarta.validation.constraints.Min;
import jakarta.validation.constraints.Digits;
import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotNull;
import jakarta.validation.constraints.Pattern;
import jakarta.validation.constraints.Size;
import java.math.BigDecimal;
import java.time.LocalDate;
import java.util.Comparator;
import java.util.List;
import net.officefloor.hq.app.session.SessionController;
import net.officefloor.hq.app.sheet.DatedSetting;
import net.officefloor.hq.app.sheet.Sheet;
import net.officefloor.hq.app.sheet.SheetService;
import org.springframework.validation.annotation.Validated;
import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.PutMapping;
import org.springframework.web.bind.annotation.RequestBody;
import org.springframework.web.bind.annotation.RequestMapping;
import org.springframework.web.bind.annotation.RestController;
import org.springframework.web.bind.annotation.SessionAttribute;

@RestController
@Validated
@RequestMapping("/api/sheets/{sheetId}")
public class SettingsController {

    /**
     * The sheet's settings as the screen shows them: the clerk limit, the floor, the terms, the late percent and the
     * cap in force on the sheet's today (the clerk limit carries two decimals, or is null for none, the floor carries
     * two decimals, the terms are whole days, the late percent carries two decimals, and the cap carries two decimals,
     * or is null for none); the policy date, null when blank (the sheet's today), and the period numbering from, null
     * when blank (off); and every value recorded for the dated settings, from which the screen works out the one in
     * force on any date.
     */
    public record SettingsView(String clerkLimit, String floor, int terms, String latePct, LocalDate policyDate,
            LocalDate periodNumberingFrom, String cap, List<DatedSettingView> dated) {
        static SettingsView of(Sheet sheet) {
            LocalDate today = sheet.getToday();
            return new SettingsView(sheet.getClerkLimit() == null ? null : sheet.getClerkLimit().toPlainString(),
                    sheet.floorOn(today).toPlainString(), sheet.termsOn(today), sheet.latePctOn(today).toPlainString(),
                    sheet.getPolicyDate(), sheet.getPeriodNumberingFrom(),
                    sheet.getCap() == null ? null : sheet.getCap().toPlainString(),
                    sheet.getSettings().stream().map(DatedSettingView::of)
                            .sorted(Comparator.comparing(DatedSettingView::key).thenComparing(DatedSettingView::from))
                            .toList());
        }
    }

    /**
     * One value recorded for a dated setting (clerk-limit, floor, terms, terms-<grade>, late-pct, cap or
     * proof-threshold), in force
     * from its from-date; null for none.
     */
    public record DatedSettingView(String key, LocalDate from, String value) {
        static DatedSettingView of(DatedSetting s) {
            return new DatedSettingView(s.getKey(), s.getFrom(), s.getValue());
        }
    }

    /**
     * The clerk limit as the form submits it: 0.00 or more with up to two decimals, or null for no limit; from the
     * date, or null for the sheet's today.
     */
    public record ClerkLimitForm(@DecimalMin("0.00") @Digits(integer = 12, fraction = 2) BigDecimal value,
            LocalDate from) {
    }

    /**
     * The cap as the form submits it: 0.00 or more with up to two decimals, or null for no cap; from the date, or
     * null for the sheet's today.
     */
    public record CapForm(@DecimalMin("0.00") @Digits(integer = 12, fraction = 2) BigDecimal value, LocalDate from) {
    }

    /**
     * The proof threshold as the form submits it: 0.00 or more with up to two decimals, or null for none; from the
     * date, or null for the sheet's today.
     */
    public record ProofThresholdForm(@DecimalMin("0.00") @Digits(integer = 12, fraction = 2) BigDecimal value,
            LocalDate from) {
    }

    /** The floor as the form submits it: 0.00 or more with up to two decimals; from the date, or null for today. */
    public record FloorForm(@NotNull @DecimalMin("0.00") @Digits(integer = 12, fraction = 2) BigDecimal value,
            LocalDate from) {
    }

    /** The terms as the form submits them: a whole number of days, 0 or more; from the date, or null for today. */
    public record TermsForm(@NotNull @Min(0) @Max(99999) Integer value, LocalDate from) {
    }

    /** The late percent as the form submits it: 0.00 or more with up to two decimals; from the date, or null for today. */
    public record LatePctForm(@NotNull @DecimalMin("0.00") @Digits(integer = 5, fraction = 2) BigDecimal value,
            LocalDate from) {
    }

    /** The policy date as the form submits it: a date, or null for blank (the sheet's today). */
    public record PolicyDateForm(LocalDate value) {
    }

    /** The period numbering from as the form submits it: a date, or null for blank (off). */
    public record PeriodNumberingFromForm(LocalDate value) {
    }

    /** The terms in force on the sheet's today for one grade that has its own, in whole days. */
    public record GradeTermsView(String grade, int terms) {
    }

    public record RoleView(String user, String role) {
        static RoleView of(SheetRole r) {
            return new RoleView(r.getUser(), r.getRole());
        }
    }

    public record RoleForm(@NotNull String role) {
    }

    private static final List<String> GRADES = List.of("A", "B", "C");

    private final SettingsService service;
    private final SheetService sheets;

    public SettingsController(SettingsService service, SheetService sheets) {
        this.service = service;
        this.sheets = sheets;
    }

    @GetMapping("/settings")
    public SettingsView settings(
            @PathVariable @NotBlank @Size(max = 100) @Pattern(regexp = "[A-Za-z0-9_.-]+") String sheetId) {
        return SettingsView.of(sheets.load(sheetId));
    }

    @PutMapping("/settings/clerk-limit")
    public SettingsView setClerkLimit(
            @PathVariable @NotBlank @Size(max = 100) @Pattern(regexp = "[A-Za-z0-9_.-]+") String sheetId,
            @Valid @RequestBody ClerkLimitForm form, @SessionAttribute(SessionController.USER) String user) {
        return SettingsView.of(service.setClerkLimit(user, sheetId, form.value(), form.from()));
    }

    @PutMapping("/settings/floor")
    public SettingsView setFloor(
            @PathVariable @NotBlank @Size(max = 100) @Pattern(regexp = "[A-Za-z0-9_.-]+") String sheetId,
            @Valid @RequestBody FloorForm form, @SessionAttribute(SessionController.USER) String user) {
        return SettingsView.of(service.setFloor(user, sheetId, form.value(), form.from()));
    }

    @PutMapping("/settings/terms")
    public SettingsView setTerms(
            @PathVariable @NotBlank @Size(max = 100) @Pattern(regexp = "[A-Za-z0-9_.-]+") String sheetId,
            @Valid @RequestBody TermsForm form, @SessionAttribute(SessionController.USER) String user) {
        return SettingsView.of(service.setTerms(user, sheetId, form.value(), form.from()));
    }

    /**
     * The terms in force on the sheet's today per grade, by grade, for each grade that has its own then; a grade not
     * listed uses the sheet's terms.
     */
    @GetMapping("/settings/grade-terms")
    public List<GradeTermsView> gradeTerms(
            @PathVariable @NotBlank @Size(max = 100) @Pattern(regexp = "[A-Za-z0-9_.-]+") String sheetId) {
        Sheet sheet = sheets.load(sheetId);
        return GRADES.stream().flatMap(g -> sheet.gradeTermsOn(g, sheet.getToday())
                .map(t -> new GradeTermsView(g, t)).stream()).toList();
    }

    @PutMapping("/settings/grade-terms/{grade}")
    public SettingsView setGradeTerms(
            @PathVariable @NotBlank @Size(max = 100) @Pattern(regexp = "[A-Za-z0-9_.-]+") String sheetId,
            @PathVariable @Pattern(regexp = "[ABC]") String grade, @Valid @RequestBody TermsForm form,
            @SessionAttribute(SessionController.USER) String user) {
        return SettingsView.of(service.setGradeTerms(user, sheetId, grade, form.value(), form.from()));
    }

    @PutMapping("/settings/late-pct")
    public SettingsView setLatePct(
            @PathVariable @NotBlank @Size(max = 100) @Pattern(regexp = "[A-Za-z0-9_.-]+") String sheetId,
            @Valid @RequestBody LatePctForm form, @SessionAttribute(SessionController.USER) String user) {
        return SettingsView.of(service.setLatePct(user, sheetId, form.value(), form.from()));
    }

    @PutMapping("/settings/policy-date")
    public SettingsView setPolicyDate(
            @PathVariable @NotBlank @Size(max = 100) @Pattern(regexp = "[A-Za-z0-9_.-]+") String sheetId,
            @Valid @RequestBody PolicyDateForm form, @SessionAttribute(SessionController.USER) String user) {
        return SettingsView.of(service.setPolicyDate(user, sheetId, form.value()));
    }

    @PutMapping("/settings/period-numbering-from")
    public SettingsView setPeriodNumberingFrom(
            @PathVariable @NotBlank @Size(max = 100) @Pattern(regexp = "[A-Za-z0-9_.-]+") String sheetId,
            @Valid @RequestBody PeriodNumberingFromForm form, @SessionAttribute(SessionController.USER) String user) {
        return SettingsView.of(service.setPeriodNumberingFrom(user, sheetId, form.value()));
    }

    @PutMapping("/settings/cap")
    public SettingsView setCap(
            @PathVariable @NotBlank @Size(max = 100) @Pattern(regexp = "[A-Za-z0-9_.-]+") String sheetId,
            @Valid @RequestBody CapForm form, @SessionAttribute(SessionController.USER) String user) {
        return SettingsView.of(service.setCap(user, sheetId, form.value(), form.from()));
    }

    @PutMapping("/settings/proof-threshold")
    public SettingsView setProofThreshold(
            @PathVariable @NotBlank @Size(max = 100) @Pattern(regexp = "[A-Za-z0-9_.-]+") String sheetId,
            @Valid @RequestBody ProofThresholdForm form, @SessionAttribute(SessionController.USER) String user) {
        return SettingsView.of(service.setProofThreshold(user, sheetId, form.value(), form.from()));
    }

    /** The roles set on the sheet, by user name; a name not listed is a clerk. */
    @GetMapping("/roles")
    public List<RoleView> roles(
            @PathVariable @NotBlank @Size(max = 100) @Pattern(regexp = "[A-Za-z0-9_.-]+") String sheetId) {
        return service.roles(sheetId).stream().map(RoleView::of).toList();
    }

    @PutMapping("/roles/{name}")
    public RoleView setRole(
            @PathVariable @NotBlank @Size(max = 100) @Pattern(regexp = "[A-Za-z0-9_.-]+") String sheetId,
            @PathVariable @NotBlank @Size(max = 100) String name,
            @Valid @RequestBody RoleForm form, @SessionAttribute(SessionController.USER) String user) {
        return RoleView.of(service.setRole(user, sheetId, name, form.role()));
    }
}
package net.officefloor.hq.app.settings;

import jakarta.persistence.Column;
import jakarta.persistence.Entity;
import jakarta.persistence.GeneratedValue;
import jakarta.persistence.GenerationType;
import jakarta.persistence.Id;
import jakarta.persistence.Table;

/** The role a user name has on a sheet; a name with none is a clerk. */
@Entity
@Table(name = "sheet_role")
public class SheetRole {

    public static final String CLERK = "clerk";
    public static final String STEWARD = "steward";

    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    private Long id;

    @Column(name = "sheet_id", nullable = false)
    private String sheetId;

    @Column(name = "user_name", nullable = false)
    private String user;

    @Column(name = "role", nullable = false)
    private String role;

    protected SheetRole() {
    }

    public SheetRole(String sheetId, String user, String role) {
        this.sheetId = sheetId;
        this.user = user;
        this.role = role;
    }

    public Long getId() {
        return id;
    }

    public String getSheetId() {
        return sheetId;
    }

    public String getUser() {
        return user;
    }

    public String getRole() {
        return role;
    }

    public void setRole(String role) {
        this.role = role;
    }
}

